using System;using IdleIntelligence.Core;using UnityEngine;using UnityEngine.UI;
namespace IdleIntelligence.Runtime {
 public sealed class HardwarePresentation:MonoBehaviour {
  GameRuntime game;ActionCard card;int index;Text price,quantity;public void Initialize(GameRuntime runtime,int i){game=runtime;index=i;card=GetComponent<ActionCard>();var colors=card.Button.colors;colors.disabledColor=Color.white;card.Button.colors=colors;GameTheme.SurfaceOn(GetComponent<Image>(),GameTheme.Surface);var row=GetComponent<HorizontalLayoutGroup>();row.padding=new RectOffset(10,10,8,8);row.spacing=8;card.Icon.GetComponent<LayoutElement>().preferredWidth=54;card.Title.font=GameTheme.Bold;card.Title.fontSize=14;card.Title.resizeTextForBestFit=true;card.Title.resizeTextMinSize=12;card.Title.resizeTextMaxSize=14;card.Detail.font=GameTheme.Body;card.Detail.fontSize=11;var holder=WorkshopUIFactory.Vertical("PurchaseCost",transform);holder.AddComponent<LayoutElement>().preferredWidth=102;var coin=WorkshopUIFactory.Node("CreditIcon",holder.transform,typeof(Image)).GetComponent<Image>();coin.sprite=game.GetComponent<MobileShell>()?.ResourceIcons[0];coin.preserveAspect=true;coin.raycastTarget=false;coin.gameObject.AddComponent<LayoutElement>().ignoreLayout=true;coin.rectTransform.anchorMin=coin.rectTransform.anchorMax=new Vector2(0,.5f);coin.rectTransform.pivot=new Vector2(0,.5f);coin.rectTransform.sizeDelta=new Vector2(20,20);price=WorkshopUIFactory.Label("CostAmount",holder.transform,"",12,34);price.alignment=TextAnchor.MiddleRight;price.resizeTextForBestFit=true;price.resizeTextMinSize=9;price.resizeTextMaxSize=12;quantity=WorkshopUIFactory.Label("BuyQuantity",holder.transform,"",11,20);quantity.alignment=TextAnchor.MiddleRight;}
  public void RefreshView(){if(game?.State==null)return;var s=game.State;var h=Balance.Hardware[index];long count=SettingsRules.BuyQuantity(s,index);var cost=Game.HardwareCost(s,index,Math.Max(1,count));card.Button.interactable=game.Writable&&count>0&&index<(ChallengeRules.Current(s)?.ClassLimit??s.Hardware.Length)&&s.Credits.CompareTo(cost)>=0;string N(ScientificNumber n)=>NumberFormatting.Format(n,s.Settings.numberFormat);card.Title.text=SettingsRules.Text(s.Settings.language,"hardware:"+h.Id);card.Detail.text="×"+s.Hardware[index]+"  ·  +"+N(ScientificNumber.From(h.Compute).Times(count))+" Compute";price.text=N(s.Credits)+" /\n"+N(cost);price.color=s.Credits.CompareTo(cost)>=0?GameTheme.Enough:GameTheme.Missing;quantity.text=SettingsRules.Text(s.Settings.language,"game:buy")+" ×"+count;quantity.color=GameTheme.Gold;if(index>=(ChallengeRules.Current(s)?.ClassLimit??s.Hardware.Length)){card.Detail.text=s.Settings.language=="de"?"In dieser Challenge gesperrt":"Locked in this challenge";quantity.text=s.Settings.language=="de"?"Gesperrt":"Locked";}}
